package com.pranit.productsupport.core.service;
import com.pranit.productsupport.contracts.*; import com.pranit.productsupport.core.domain.*; import com.pranit.productsupport.core.repository.*; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.List; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TicketService {
 private final TicketRepository tickets;private final AppUserRepository users;private final OrderItemRepository items;private final IdempotencyKeyRepository keys;private final TicketTransactionService tx;private final TicketCommentRepository comments;private final TicketStatusHistoryRepository history;private final ServiceQuoteRepository quotes;private final OutboxService outbox;private final long quoteExpiryHours;
 public TicketService(TicketRepository t,AppUserRepository u,OrderItemRepository i,IdempotencyKeyRepository k,TicketTransactionService tx,TicketCommentRepository c,TicketStatusHistoryRepository h,ServiceQuoteRepository q,OutboxService o,@org.springframework.beans.factory.annotation.Value("${app.payments.quote-expiry-hours:72}") long quoteExpiryHours){tickets=t;users=u;items=i;keys=k;this.tx=tx;comments=c;history=h;quotes=q;outbox=o;this.quoteExpiryHours=quoteExpiryHours;}
 public TicketResponse create(Long userId,String key,CreateTicketRequest req){if(key==null||key.isBlank()||key.length()>100||!key.matches("[A-Za-z0-9._:-]{8,100}"))throw new ApiException(HttpStatus.BAD_REQUEST,"Idempotency-Key must be 8-100 characters using letters, numbers, dot, underscore, colon or hyphen");try{return tx.create(userId,key,req);}catch(DataIntegrityViolationException e){var existing=keys.findByUser_IdAndKey(userId,key);if(existing.isPresent()){IdempotencyKey old=existing.get();if(!old.getRequestHash().equals(RequestHash.ticket(userId,req)))throw ApiException.conflict("Idempotency-Key was already used with a different request body");if(old.getTicket()!=null)return tx.findResponseById(old.getTicket().getId());throw ApiException.conflict("An identical request is still processing; retry shortly");}throw e;}}
 @Transactional(readOnly=true) public TicketPageResponse myTickets(Long userId,int page,int size){if(page<0||size<1)throw new ApiException(HttpStatus.BAD_REQUEST,"page must be >= 0 and size >= 1");int safeSize=Math.min(size,100);var result=tickets.findByCustomer_IdOrderByCreatedAtDesc(userId,PageRequest.of(page,safeSize,Sort.by(Sort.Direction.DESC,"createdAt")));return new TicketPageResponse(result.getContent().stream().map(tx::dto).toList(),result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages());}
 @Transactional(readOnly=true) public TicketPageResponse queue(TicketStatus status,int page,int size){if(page<0||size<1)throw new ApiException(HttpStatus.BAD_REQUEST,"page must be >= 0 and size >= 1");int safeSize=Math.min(size,100);var result=(status==null?tickets.findAll(PageRequest.of(page,safeSize,Sort.by(Sort.Direction.ASC,"createdAt"))):tickets.findByStatusOrderByCreatedAtAsc(status,PageRequest.of(page,safeSize)));return new TicketPageResponse(result.getContent().stream().map(tx::dto).toList(),result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages());}
 @Transactional(readOnly=true) public TicketResponse get(Long ticketId,Long actorId,boolean support){Ticket t=tickets.findById(ticketId).orElseThrow(()->ApiException.notFound("Ticket not found"));if(!support&&!t.getCustomer().getId().equals(actorId))throw ApiException.notFound("Ticket not found");return tx.dto(t);}
 @Transactional public CommentResponse addComment(Long ticketId,Long actorId,UserRole role,String content){Ticket t=tickets.findById(ticketId).orElseThrow(()->ApiException.notFound("Ticket not found"));if(role==UserRole.CUSTOMER&&!t.getCustomer().getId().equals(actorId))throw ApiException.notFound("Ticket not found");if(t.getStatus()==TicketStatus.CLOSED||t.getStatus()==TicketStatus.REJECTED)throw ApiException.conflict("Comments cannot be added to a terminal ticket");AppUser actor=users.findById(actorId).orElseThrow(()->ApiException.notFound("User not found"));TicketComment c=comments.save(new TicketComment(t,actor,role,content.trim()));return new CommentResponse(c.getId(),ticketId,actorId,role.name(),c.getContent(),c.getCreatedAt());}
 @Transactional(readOnly=true) public List<CommentResponse> comments(Long ticketId,Long actorId,boolean support){Ticket t=tickets.findById(ticketId).orElseThrow(()->ApiException.notFound("Ticket not found"));if(!support&&!t.getCustomer().getId().equals(actorId))throw ApiException.notFound("Ticket not found");return comments.findByTicket_IdOrderByCreatedAtAsc(ticketId).stream().map(c->new CommentResponse(c.getId(),ticketId,c.getAuthor().getId(),c.getAuthorRole().name(),c.getContent(),c.getCreatedAt())).toList();}
 @Transactional public TicketResponse assign(Long ticketId,Long actorId,Long assigneeId){Ticket t=tickets.findById(ticketId).orElseThrow(()->ApiException.notFound("Ticket not found"));AppUser assignee=users.findById(assigneeId).orElseThrow(()->ApiException.notFound("Support agent not found"));if(assignee.getRole()!=UserRole.SUPPORT_AGENT||!assignee.isActive())throw new ApiException(HttpStatus.BAD_REQUEST,"Assignee must be an active support agent");AppUser actor=users.findById(actorId).orElseThrow(()->ApiException.notFound("User not found"));t.setAssignedTo(assignee);outbox.enqueue("TicketAssigned",t.getId().toString(),java.util.Map.of("ticketId",t.getId(),"assignedTo",assignee.getId(),"assignedBy",actor.getId(),"occurredAt",Instant.now().toString()));return tx.dto(t);}
 @Transactional public TicketResponse updateStatus(Long ticketId,Long actorId,TicketStatus next,String note){Ticket t=tickets.findById(ticketId).orElseThrow(()->ApiException.notFound("Ticket not found"));TicketStatus prev=t.getStatus();if(!TicketStatusPolicy.canTransition(prev,next))throw ApiException.conflict("Unsupported ticket status transition: "+prev+" -> "+next);AppUser actor=users.findById(actorId).orElseThrow(()->ApiException.notFound("User not found"));t.setStatus(next);history.save(new TicketStatusHistory(t,prev,next,actor,note));outbox.enqueue("TicketStatusChanged",t.getId().toString(),new TicketStatusChangedEvent(t.getId(),prev.name(),next.name(),actorId,Instant.now()));return tx.dto(t);}
 @Transactional public QuoteResponse createQuote(Long ticketId,Long actorId,CreateQuoteRequest req){Ticket t=tickets.findById(ticketId).orElseThrow(()->ApiException.notFound("Ticket not found"));if(t.getStatus()==TicketStatus.CLOSED||t.getStatus()==TicketStatus.REJECTED)throw ApiException.conflict("Cannot quote a terminal ticket");AppUser actor=users.findById(actorId).orElseThrow(()->ApiException.notFound("User not found"));ServiceQuote q=quotes.save(new ServiceQuote(t,actor,req.amountPaise(),req.description().trim(),Instant.now().plus(quoteExpiryHours,ChronoUnit.HOURS)));return quoteDto(q);}
 @Transactional(readOnly=true) public QuoteResponse getQuote(Long quoteId,Long actorId,boolean support){ServiceQuote q=(support?quotes.findById(quoteId):quotes.findByIdAndTicket_Customer_Id(quoteId,actorId)).orElseThrow(()->ApiException.notFound("Quote not found"));return quoteDto(q);}
 public static QuoteResponse quoteDto(ServiceQuote q){return new QuoteResponse(q.getId(),q.getTicket().getId(),q.getAmountPaise(),q.getCurrency(),q.getDescription(),q.getStatus(),q.getExpiresAt(),q.getCreatedAt());}
}
